import React from "react";
import { render, fireEvent } from "@testing-library/react-native";
import Header from "../Header";

// Mock all problematic imports at the module level with simpler approach
jest.mock("../CoinsDisplay", () => {
  const { View, Text, TouchableOpacity } = require("react-native");
  return function MockCoinsDisplay({ coins, onPress }: any) {
    if (onPress) {
      return (
        <TouchableOpacity testID="coins-display-touchable" onPress={onPress}>
          <View testID="coins-display">
            <Text>{coins}</Text>
          </View>
        </TouchableOpacity>
      );
    }

    return (
      <View testID="coins-display">
        <Text>{coins}</Text>
      </View>
    );
  };
});

jest.mock("../icons/HintIcon", () => {
  const { View } = require("react-native");
  return function MockHintIcon(props: any) {
    return (
      <View
        testID="hinticon-icon"
        style={{ width: props.width || 24, height: props.height || 24 }}
      />
    );
  };
});

describe("Header", () => {
  const defaultProps = {
    userCoins: 25,
    onHintPress: jest.fn(),
    onCoinsPress: jest.fn(),
  };

  beforeEach(() => {
    jest.clearAllMocks();
  });

  describe("Rendering", () => {
    it("renders header correctly", () => {
      const { getByTestId } = render(<Header {...defaultProps} />);

      expect(getByTestId("header")).toBeTruthy();
      expect(getByTestId("header-left-side")).toBeTruthy();
      expect(getByTestId("header-right-side")).toBeTruthy();
    });

    it("renders hint button with correct text", () => {
      const { getByText, getByTestId } = render(<Header {...defaultProps} />);

      expect(getByTestId("hint-button")).toBeTruthy();
      expect(getByText("Hint")).toBeTruthy();
    });

    it("renders coins display with correct amount", () => {
      const { getByTestId, getByText } = render(<Header {...defaultProps} />);

      expect(getByTestId("coins-display")).toBeTruthy();
      expect(getByText("25")).toBeTruthy();
    });

    it("renders hint icon", () => {
      const { getByTestId } = render(<Header {...defaultProps} />);

      expect(getByTestId("hinticon-icon")).toBeTruthy();
    });

    it("has correct header layout structure", () => {
      const { getByTestId } = render(<Header {...defaultProps} />);

      const header = getByTestId("header");
      expect(header.props.className).toContain(
        "w-full flex-row items-center justify-between"
      );
    });

    it("displays different coin amounts correctly", () => {
      const { getByText, rerender } = render(
        <Header {...defaultProps} userCoins={0} />
      );

      expect(getByText("0")).toBeTruthy();

      rerender(<Header {...defaultProps} userCoins={100} />);
      expect(getByText("100")).toBeTruthy();

      rerender(<Header {...defaultProps} userCoins={9999} />);
      expect(getByText("9999")).toBeTruthy();
    });
  });

  describe("Component Integration", () => {
    it("integrates CoinsDisplay correctly as touchable", () => {
      const { getByTestId } = render(<Header {...defaultProps} />);

      expect(getByTestId("coins-display-touchable")).toBeTruthy();
    });

    it("passes correct props to CoinsDisplay", () => {
      const { getByText } = render(<Header {...defaultProps} userCoins={42} />);

      expect(getByText("42")).toBeTruthy();
    });

    it("renders hint button with proper styling", () => {
      const { getByTestId } = render(<Header {...defaultProps} />);

      const hintButton = getByTestId("hint-button");
      expect(hintButton.props.className).toContain("items-center p-2");
    });

    it("maintains correct layout spacing", () => {
      const { getByTestId } = render(<Header {...defaultProps} />);

      const leftSide = getByTestId("header-left-side");
      expect(leftSide.props.className).toContain(
        "flex-row items-center space-x-3"
      );
    });
  });

  describe("Button Interactions", () => {
    it("calls onHintPress when hint button is pressed", () => {
      const { getByTestId } = render(<Header {...defaultProps} />);

      const hintButton = getByTestId("hint-button");
      fireEvent.press(hintButton);

      expect(defaultProps.onHintPress).toHaveBeenCalledTimes(1);
    });

    it("calls onCoinsPress when coins are pressed", () => {
      const { getByTestId } = render(<Header {...defaultProps} />);

      const coinsDisplay = getByTestId("coins-display-touchable");
      fireEvent.press(coinsDisplay);

      expect(defaultProps.onCoinsPress).toHaveBeenCalledTimes(1);
    });

    it("handles multiple hint button presses", () => {
      const { getByTestId } = render(<Header {...defaultProps} />);

      const hintButton = getByTestId("hint-button");

      fireEvent.press(hintButton);
      fireEvent.press(hintButton);
      fireEvent.press(hintButton);

      expect(defaultProps.onHintPress).toHaveBeenCalledTimes(3);
    });

    it("handles multiple coins presses", () => {
      const { getByTestId } = render(<Header {...defaultProps} />);

      const coinsDisplay = getByTestId("coins-display-touchable");

      fireEvent.press(coinsDisplay);
      fireEvent.press(coinsDisplay);

      expect(defaultProps.onCoinsPress).toHaveBeenCalledTimes(2);
    });

    it("handles simultaneous button interactions", () => {
      const { getByTestId } = render(<Header {...defaultProps} />);

      const hintButton = getByTestId("hint-button");
      const coinsDisplay = getByTestId("coins-display-touchable");

      fireEvent.press(hintButton);
      fireEvent.press(coinsDisplay);
      fireEvent.press(hintButton);

      expect(defaultProps.onHintPress).toHaveBeenCalledTimes(2);
      expect(defaultProps.onCoinsPress).toHaveBeenCalledTimes(1);
    });
  });

  describe("Accessibility", () => {
    it("has proper header accessibility properties", () => {
      const { getByTestId } = render(<Header {...defaultProps} />);

      const header = getByTestId("header");
      expect(header.props.accessible).toBeTruthy();
      expect(header.props.accessibilityRole).toBe("none");
      expect(header.props.accessibilityLabel).toBe(
        "Game header with hint button and coin balance"
      );
    });

    it("has proper hint button accessibility properties", () => {
      const { getByTestId } = render(<Header {...defaultProps} />);

      const hintButton = getByTestId("hint-button");
      expect(hintButton.props.accessible).toBeTruthy();
      expect(hintButton.props.accessibilityRole).toBe("button");
      expect(hintButton.props.accessibilityLabel).toBe(
        "Get hint for current riddle"
      );
    });

    it("provides proper test IDs for all interactive elements", () => {
      const { getByTestId } = render(<Header {...defaultProps} />);

      expect(getByTestId("header")).toBeTruthy();
      expect(getByTestId("hint-button")).toBeTruthy();
      expect(getByTestId("coins-display-touchable")).toBeTruthy();
      expect(getByTestId("header-left-side")).toBeTruthy();
      expect(getByTestId("header-right-side")).toBeTruthy();
    });

    it("maintains accessibility with different coin amounts", () => {
      const { getByTestId } = render(
        <Header {...defaultProps} userCoins={0} />
      );

      const header = getByTestId("header");
      expect(header.props.accessibilityLabel).toBe(
        "Game header with hint button and coin balance"
      );
    });
  });

  describe("Edge Cases", () => {
    it("handles zero coins correctly", () => {
      const { getByText } = render(<Header {...defaultProps} userCoins={0} />);

      expect(getByText("0")).toBeTruthy();
    });

    it("handles negative coins gracefully", () => {
      const { getByText } = render(
        <Header {...defaultProps} userCoins={-10} />
      );

      expect(getByText("-10")).toBeTruthy();
    });

    it("handles very large coin amounts", () => {
      const { getByText } = render(
        <Header {...defaultProps} userCoins={999999} />
      );

      expect(getByText("999999")).toBeTruthy();
    });

    it("handles undefined callbacks gracefully", () => {
      const { getByTestId } = render(
        <Header
          userCoins={25}
          onHintPress={undefined as any}
          onCoinsPress={undefined as any}
        />
      );

      expect(() => {
        fireEvent.press(getByTestId("hint-button"));
        fireEvent.press(getByTestId("coins-display-touchable"));
      }).not.toThrow();
    });

    it("handles floating point coin amounts", () => {
      const { getByText } = render(
        <Header {...defaultProps} userCoins={25.5} />
      );

      expect(getByText("25.5")).toBeTruthy();
    });

    it("maintains layout integrity with extreme coin values", () => {
      const { getByTestId } = render(
        <Header {...defaultProps} userCoins={0} />
      );

      const header = getByTestId("header");
      const leftSide = getByTestId("header-left-side");
      const rightSide = getByTestId("header-right-side");

      expect(header).toBeTruthy();
      expect(leftSide).toBeTruthy();
      expect(rightSide).toBeTruthy();
    });
  });

  describe("Performance", () => {
    it("updates correctly when userCoins prop changes", () => {
      const { getByText, rerender } = render(
        <Header {...defaultProps} userCoins={10} />
      );

      expect(getByText("10")).toBeTruthy();

      rerender(<Header {...defaultProps} userCoins={50} />);
      expect(getByText("50")).toBeTruthy();
    });

    it("handles rapid coin value changes efficiently", () => {
      const { rerender } = render(<Header {...defaultProps} />);

      // Simulate rapid coin value changes
      for (let i = 0; i < 20; i++) {
        rerender(<Header {...defaultProps} userCoins={i * 10} />);
      }

      // Should not throw errors
      expect(true).toBe(true);
    });

    it("handles callback prop changes efficiently", () => {
      const { rerender } = render(<Header {...defaultProps} />);

      // Simulate callback changes
      for (let i = 0; i < 10; i++) {
        const newOnHintPress = jest.fn();
        const newOnCoinsPress = jest.fn();
        rerender(
          <Header
            {...defaultProps}
            onHintPress={newOnHintPress}
            onCoinsPress={newOnCoinsPress}
          />
        );
      }

      // Should not throw errors
      expect(true).toBe(true);
    });

    it("maintains interaction functionality after rapid updates", () => {
      const { getByTestId, rerender } = render(<Header {...defaultProps} />);

      // Rapid updates
      for (let i = 0; i < 5; i++) {
        rerender(<Header {...defaultProps} userCoins={i * 100} />);
      }

      // Test interactions still work
      const hintButton = getByTestId("hint-button");
      fireEvent.press(hintButton);

      expect(defaultProps.onHintPress).toHaveBeenCalledTimes(1);
    });

    it("handles concurrent prop and interaction updates", () => {
      const { getByTestId, rerender } = render(<Header {...defaultProps} />);

      const hintButton = getByTestId("hint-button");

      // Interleave prop changes and interactions
      fireEvent.press(hintButton);
      rerender(<Header {...defaultProps} userCoins={100} />);
      fireEvent.press(hintButton);
      rerender(<Header {...defaultProps} userCoins={200} />);

      expect(defaultProps.onHintPress).toHaveBeenCalledTimes(2);
    });
  });
});
